shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-dark: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --crimson: #8f241e;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    overflow-x: hidden;
    position: relative;
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Top Reading Progress Bar */
  #progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    width: 0%;
    background: var(--accent);
    z-index: 1000;
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 900;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line-dark);
    padding: 0.75rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-cluster {
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .section-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    padding: 0.18rem 0.5rem;
    border-radius: 2px;
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--ink);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
    flex-shrink: 0;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.76rem;
    font-weight: 600;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
    letter-spacing: 0.04em;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .page-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  /* Hero Header */
  .article-hero {
    border-bottom: 3px double var(--ink);
    padding-bottom: 2.25rem;
    margin-bottom: 2.75rem;
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 1rem;
  }

  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 24px;
    height: 2px;
    background: var(--accent);
  }

  .hero-title {
    font-family: var(--font-display);
    font-weight: 800;
    color: var(--ink);
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.2;
    letter-spacing: -0.015em;
    margin-bottom: 1.5rem;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.32;
    letter-spacing: 0;
  }

  .hero-meta-grid {
    display: grid;
    grid-template-columns: 1fr auto;
    align-items: end;
    gap: 1.5rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
  }

  .byline-block {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    color: var(--muted);
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.6rem 1.25rem;
  }

  .byline-author {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.03em;
    text-transform: uppercase;
  }

  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.8rem;
  }

  .docket-stamp {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--ink);
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-left: 3px solid var(--crimson);
    padding: 0.45rem 0.85rem;
    letter-spacing: 0.04em;
  }

  /* Two-Column Editorial Architecture */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 360px;
    gap: 3.25rem;
    align-items: start;
  }

  .narrative-col {
    min-width: 0;
  }

  .forensic-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2rem;
    position: sticky;
    top: 4.5rem;
  }

  /* Section Dividers within Narrative */
  .act-header {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin: 2.5rem 0 1.25rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid var(--line-dark);
  }

  .act-header:first-child {
    margin-top: 0;
  }

  .act-num {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.15rem 0.45rem;
    letter-spacing: 0.06em;
  }

  .act-title {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
  }

  /* Prose Typography */
  .prose-p {
    font-family: var(--font-serif);
    font-size: 1.125rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.45rem;
  }

  :host([lang="en"]) .prose-p {
    line-height: 1.78;
  }

  /* Lead Paragraph Styling (No ::first-letter on Chinese) */
  .prose-lead {
    font-size: 1.26rem;
    line-height: 1.82;
    font-weight: 600;
    color: var(--ink);
    padding-left: 1.15rem;
    border-left: 4px solid var(--accent);
    margin-bottom: 1.75rem;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 0.15em;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
    font-weight: 600;
  }

  /* Judicial Order Callout Box (in-stream) */
  .court-mandate-box {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-left: 4px solid var(--ink);
    padding: 1.35rem 1.5rem;
    margin: 1.65rem 0;
    position: relative;
  }

  .court-mandate-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--crimson);
    font-weight: 700;
    margin-bottom: 0.55rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .court-mandate-box .prose-p {
    margin-bottom: 0;
    font-size: 1.06rem;
  }

  /* Official Response Mini-Strip */
  .response-strip {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin: 1.65rem 0;
    padding: 1.15rem;
    background: var(--paper-deep);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-dark);
  }

  .response-cell {
    padding: 0.25rem 0.5rem;
  }

  .response-cell + .response-cell {
    border-left: 1px solid var(--line-dark);
    padding-left: 1.15rem;
  }

  .response-agency {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.4rem;
  }

  .response-cell .prose-p {
    font-size: 0.98rem;
    line-height: 1.68;
    margin-bottom: 0;
  }

  /* Split Sentence Verdict Quote (p10.s2) */
  .verdict-quote {
    margin: 2rem 0;
    padding: 1.75rem 1.85rem;
    background: var(--navy-bg);
    color: var(--paper);
    border-left: 5px solid var(--accent);
    font-family: var(--font-display);
    font-size: 1.18rem;
    line-height: 1.72;
    position: relative;
  }

  .verdict-quote::before {
    content: "PLAINTIFFS' CONSTITUTIONAL ARGUMENT · 原告核心法理指控";
    display: block;
    font-family: var(--font-mono);
    font-size: 0.7rem;
    letter-spacing: 0.1em;
    color: #e2965c;
    margin-bottom: 0.85rem;
    font-weight: 600;
  }

  /* Sidebar Dossier Cards */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-top: 3px solid var(--ink);
    padding: 1.35rem;
  }

  .dossier-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-bottom: 1px solid var(--line-dark);
    padding-bottom: 0.65rem;
    margin-bottom: 1rem;
  }

  .dossier-title {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
  }

  .dossier-tag {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    color: var(--accent);
    font-weight: 600;
  }

  /* Derived Pull Quote Card in Sidebar (q1) */
  .pull-quote {
    background: var(--paper);
    border: 1px solid var(--line-dark);
    padding: 1.15rem;
    margin-top: 0.5rem;
  }

  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.02rem;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 0.65rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* SVG Diagram Containers */
  .svg-wrapper {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 0.5rem;
  }

  .svg-caption {
    font-family: var(--font-sans);
    font-size: 0.76rem;
    color: var(--muted);
    line-height: 1.5;
    margin-top: 0.75rem;
  }

  /* Full-width Timeline Section below main grid */
  .chronology-banner {
    margin-top: 3.5rem;
    padding-top: 2.25rem;
    border-top: 2px solid var(--ink);
  }

  .chronology-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .chronology-title {
    font-family: var(--font-display);
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
  }

  .chronology-sub {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  /* Editorial Footer */
  .article-footer {
    margin-top: 3.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line-dark);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2.25rem;
    }

    .forensic-rail {
      position: static;
    }

    .hero-meta-grid {
      grid-template-columns: 1fr;
      gap: 1rem;
    }
  }

  @media (max-width: 600px) {
    .masthead {
      padding: 0.65rem 1rem;
    }

    .page-shell {
      padding: 1.5rem 1rem 3.5rem;
    }

    .response-strip {
      grid-template-columns: 1fr;
    }

    .response-cell + .response-cell {
      border-left: none;
      border-top: 1px solid var(--line-dark);
      padding-left: 0.5rem;
      padding-top: 0.85rem;
    }

    .verdict-quote {
      padding: 1.25rem;
      font-size: 1.05rem;
    }

    .prose-lead {
      font-size: 1.12rem;
    }
  }
